import sys
from collections import defaultdict, deque

def bfs(tree, start):
    dist = [-1] * (len(tree) + 1)
    dist[start] = 0
    queue = deque([start])
    while queue:
        node = queue.popleft()
        for neighbor in tree[node]:
            if dist[neighbor] == -1:
                dist[neighbor] = dist[node] + 1
                queue.append(neighbor)
    return dist

def find_farthest_node(tree, start):
    dist = bfs(tree, start)
    max_dist = max(dist)
    farthest_node = dist.index(max_dist)
    return farthest_node, max_dist

def lca(tree, u, v, parent, depth):
    if depth[u] < depth[v]:
        u, v = v, u
    diff = depth[u] - depth[v]
    for i in range(18, -1, -1):
        if diff & (1 << i):
            u = parent[u][i]
    if u != v:
        for i in range(18, -1, -1):
            if parent[u][i] != parent[v][i]:
                u = parent[u][i]
                v = parent[v][i]
        u = parent[u][0]
    return u

def main():
    import sys
    input = sys.stdin.read().split()
    n = int(input[0])
    edges = [(int(input[2*i+1]), int(input[2*i+2])) for i in range(n-1)]

    tree = defaultdict(list)
    for u, v in edges:
        tree[u].append(v)
        tree[v].append(u)

    farthest_node, _ = find_farthest_node(tree, 1)
    diameter_end, diameter = find_farthest_node(tree, farthest_node)

    parent = [[-1] * 18 for _ in range(n + 1)]
    depth = [0] * (n + 1)
    stack = [(farthest_node, -1, 0)]
    while stack:
        node, par, dep = stack.pop()
        parent[node][0] = par
        depth[node] = dep
        for neighbor in tree[node]:
            if neighbor != par:
                stack.append((neighbor, node, dep + 1))

    for k in range(1, 18):
        for i in range(1, n + 1):
            if parent[i][k - 1] != -1:
                parent[i][k] = parent[parent[i][k - 1]][k - 1]

    l = lca(tree, farthest_node, diameter_end, parent, depth)

    max_common = 0
    max_total_length = 0
    best_pair = None

    for u in tree[l]:
        dist_u = bfs(tree, u)
        for v in tree[l]:
            if u != v:
                dist_v = bfs(tree, v)
                common_length = depth[l] * 2 - depth[u] - depth[v] + dist_u[diameter_end] + dist_v[diameter_end]
                total_length = dist_u[diameter_end] + dist_v[diameter_end]
                if total_length > max_total_length or (total_length == max_total_length and common_length > max_common):
                    max_common = common_length
                    max_total_length = total_length
                    best_pair = (u, v)

    x1, y1 = farthest_node, diameter_end
    x2, y2 = best_pair

    print(x1, y1)
    print(x2, y2)

main()
